package com.calitrack.entity;

import jakarta.persistence.*;
import lombok.Getter;
import lombok.Setter;
import java.time.Instant;
import java.util.UUID;

@Entity
@Table(
    name = "workouts",
    uniqueConstraints = @UniqueConstraint(name = "uq_workouts_user_id_client_id", columnNames = {"user_id", "client_id"})
)
@Getter
@Setter
public class Workout {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(nullable = false)
    private String userId;

    // Generated by the phone when the workout starts. Unique for each user, so a retried finish
    // finds the workout it already saved.
    @Column(nullable = false)
    private UUID clientId;

    @Column(nullable = false)
    private Instant startTime;

    @Column(nullable = false)
    private Instant endTime;

    private String notes;
}
